/* =============================== Google Sheets integration (optional) ========
   Paste your deployed Apps Script Web App URL below (see the accompanying
   GoogleAppsScript-Code.gs.txt file for setup steps). When this is empty,
   the app works exactly as before — pure localStorage + the demo accounts
   below. Once you paste a URL here, login and unit/department management
   switch to reading and writing your Google Sheet instead. */
const SHEETS_API_URL = "https://script.google.com/macros/s/AKfycbwKf9MuuHoAKSwbWKJ4fyLERi1OCHh61V5KGPkCQRkk5pYdm289dOHJ0c2_mGi_bHeB/exec";

async function callSheetsApi(action, payload) {
  if (!SHEETS_API_URL) return { ok: false, error: "لم يتم ربط الموقع بجوجل شيت بعد" };
  try {
    // GET بمعامِلات الرابط بدل POST — أكثر توافقًا مع طريقة تعامل بعض
    // المتصفحات مع تحويلات (redirects) تطبيقات ويب Google Apps Script.
    const qs = `?action=${encodeURIComponent(action)}&payload=${encodeURIComponent(JSON.stringify(payload || {}))}`;
    const res = await fetch(SHEETS_API_URL + qs);
    return await res.json();
  } catch (err) {
    return { ok: false, error: "تعذر الاتصال بجوجل شيت. تحققي من الاتصال بالإنترنت." };
  }
}
function sheetsConfigured() { return !!SHEETS_API_URL; }

